SELECT COUNT(*) FROM dev_product WHERE 1 = 1
AND (product_key ILIKE CONCAT('%', #{keyword}, '%') OR name ILIKE CONCAT('%', #{keyword}, '%'))
AND status = #{status}

SELECT id, product_key AS productKey, name, device_type AS deviceType, status, archived_at AS archivedAt, created_at AS createdAt, updated_at AS updatedAt, version FROM dev_product WHERE 1 = 1
AND (product_key ILIKE CONCAT('%', #{keyword}, '%') OR name ILIKE CONCAT('%', #{keyword}, '%'))
AND status = #{status}
ORDER BY created_at DESC, id OFFSET #{offset} LIMIT #{limit}

SELECT COUNT(*) FROM dev_device WHERE 1 = 1
AND product_id = #{productId}
AND (device_code ILIKE CONCAT('%', #{keyword}, '%') OR name ILIKE CONCAT('%', #{keyword}, '%'))
AND status = #{status}

SELECT id, product_id AS productId, device_code AS deviceCode, name, status, archived_at AS archivedAt, created_at AS createdAt, updated_at AS updatedAt, version FROM dev_device WHERE 1 = 1
AND product_id = #{productId}
AND (device_code ILIKE CONCAT('%', #{keyword}, '%') OR name ILIKE CONCAT('%', #{keyword}, '%'))
AND status = #{status}
ORDER BY created_at DESC, id OFFSET #{offset} LIMIT #{limit}

